contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address proposedAddress, string memory typeStr) public {
        require(bytes(typeStr).length > 0, "type must be non-empty");

        c.init(address(0x1), address(0x2), address(0x3));
        uint countBefore = c.proposalCount();
        c.newAddressProposal(proposedAddress, typeStr);
        uint id1 = countBefore + 1;
        uint countAfterFirst = c.proposalCount();
        c.newAddressProposal(proposedAddress, typeStr);
        uint id2 = countAfterFirst + 1;

        string memory storedTypeBefore = c.mapPID_type(id1);
        uint votesBefore = c.mapPID_votes(id1);

        uint voteWeight = c.voteProposal(id1);

        assert(
            c.proposalCount() >= id2 &&
            keccak256(bytes(c.mapPID_type(id1))) == keccak256(bytes(storedTypeBefore)) &&
            c.mapPID_votes(id1) >= votesBefore &&
            c.mapPIDMember_votes(id1, address(this)) == voteWeight &&
            voteWeight <= c.mapPID_votes(id1)
        );
    }
}

